async function renderOrganizationInvestigation(ticket){
 const host=$('#organization-investigation-content'),id=prototypeUI.caseId;host.replaceChildren(element('p','Reading saved investigation…','hint'));if(!id){host.replaceChildren(element('p','Choose an investigation from the overview.','hint'));return;}
 const d=await request('/api/workspace/cases?id='+encodeURIComponent(id));if(ticket!==organizationUI.load||state.view!=='decisions'||organizationUI.mode!=='investigation')return;
 if(d.case?.project_id!==organizationUI.projectId){host.replaceChildren(element('p','This investigation belongs to another context. Switch to its saved context to review it.','hint'));return;}
 organizationUI.investigation=d;host.replaceChildren(element('p','INVESTIGATION · '+d.case.status.replaceAll('_',' ').toUpperCase(),'eyebrow'),element('h3',d.case.title),element('p',d.case.question));
 append(host,element('h4','Evidence'),element('p','Source facts and user-reviewed associations are separate from business impact.','hint'));
 for(const e of d.evidence||[])host.append(organizationEvidenceLink(e));if(!d.evidence?.length)host.append(element('p','No source evidence is attached yet.','hint'));
 host.append(element('h4','Impact and assumptions'));
 for(const s of d.impact_scenarios||[])append(host,element('p',s.interpretation||'Saved explicit-input scenario'),factList(Object.entries(s.calculation||{})),element('p','Input basis: '+s.input_basis+' · '+(s.inputs?.assumption_note||'')+' · not a forecast or confirmed loss.','hint'));
 if(!d.impact_scenarios?.length)host.append(element('p','No business impact scenario has been saved. No loss or exposure is inferred.','hint'));
 host.append(element('h4','Reviews and next steps'));for(const r of (d.reviews||[]).filter(r=>r.kind==='human_review'))append(host,element('p',r.payload.conclusion.replaceAll('_',' ')+' · '+r.payload.note));
 for(const a of d.actions||[])append(host,element('strong',a.title),element('p',a.status.replaceAll('_',' ')+' · '+(a.owner||'Owner not assigned')+(a.due_at?' · Due '+compactClock(a.due_at):''),'minor'),element('p',a.notes||'No further instructions saved.'));
 if(!d.actions?.length&&!d.reviews?.some(r=>r.kind==='human_review'))host.append(element('p','No reviewed recommendation or action is saved yet.','hint'));
 if(organizationUI.workspace?.capabilities?.llm?.configured)host.append(organizationButton('Ask advisor about this investigation',()=>organizationRoute('advisor',organizationUI.projectId,id)));
}
async function organizationRead(){
 if(!$('#organization-empty'))return;const ticket=++organizationUI.load;organizationUI.mode=organizationModes.includes(organizationUI.mode)?organizationUI.mode:'overview';
 if(organizationUI.mode==='business-create'&&!organizationUI.projectId){organizationUI.project=null;organizationVisibility(organizationUI.mode);renderBusinessCreator();$('#organization-status').textContent='';return;}
 if(organizationUI.mode==='create'){renderOrganizationEditor();$('#organization-status').textContent='';return;}
 if(organizationUI.mode==='edit'&&organizationUI.project?.id===organizationUI.projectId)renderOrganizationEditor();
 organizationVisibility(organizationUI.mode);$('#organization-status').textContent='Reading saved organizations…';
 try{
  const data=await request('/api/workspace');if(ticket!==organizationUI.load||state.view!=='decisions')return;organizationUI.workspace=data;
  const projects=(data.projects||[]).filter(p=>p.id!=='proto_project_linked_ops_v02');let current=projects.find(p=>p.id===organizationUI.projectId);
  if(!organizationUI.projectId&&prototypeUI.caseId&&organizationUI.mode!=='demo'){const c=(data.cases||[]).find(c=>c.id===prototypeUI.caseId);if(c?.project_id==='proto_project_linked_ops_v02')organizationUI.mode='demo';else if(c){current=projects.find(p=>p.id===c.project_id);organizationUI.projectId=current?.id||null;organizationUI.mode='investigation';}else if(organizationUI.mode==='overview')organizationUI.mode='demo';}
  if(!organizationUI.projectId&&organizationUI.mode!=='demo'){current=projects.find(p=>p.id===lastOrganization())||projects.find(p=>p.kind==='organization');organizationUI.projectId=current?.id||null;}
  organizationUI.project=current||null;organizationSwitcher(projects);organizationVisibility(organizationUI.mode);
  if(organizationUI.mode==='demo'){$('#organization-status').textContent='Synthetic demonstration. Your organization profiles remain separate.';await prototypeRead();return;}
  if(!current){organizationUI.mode='overview';organizationVisibility('overview');$('#organization-status').textContent=organizationUI.projectId?'Selected context was not found. Choose a saved context or create an organization.':'';return;}
  rememberOrganization(current.id);renderOrganizationIdentity(current);writeLocation('replace');$('#organization-status').textContent='';
  if(organizationUI.mode==='edit'){renderOrganizationEditor();return;}
  if(organizationUI.mode==='business-create'){renderBusinessCreator();return;}
  if(organizationUI.mode==='business-review'){await renderBusinessReview();return;}
  if(organizationUI.mode==='find'){renderOrganizationFind();return;}
  if(organizationUI.mode==='details'){await renderOrganizationDetails(ticket);return;}
  if(organizationUI.mode==='investigation'){await renderOrganizationInvestigation(ticket);return;}
  if(organizationUI.mode==='advisor'){
   const ready=!!data.capabilities?.llm?.configured,scopedCase=(data.cases||[]).some(c=>c.id===prototypeUI.caseId&&c.project_id===current.id);$('#organization-advisor-form').hidden=!ready||!scopedCase;
   $('#organization-advisor-status').textContent=!ready?'Advisor setup is required. No generated answer is available.':!scopedCase?'Open a saved investigation to ask an evidence-grounded question.':'Responses use the selected investigation and saved evidence. Generated claims still need review.';return;
  }
  renderOrganizationOverview(data);await renderOrganizationSavedEvidence(ticket);
 }catch(e){if(ticket!==organizationUI.load||state.view!=='decisions')return;organizationVisibility(organizationUI.mode);$('#organization-status').textContent=e.message;notice(e.message,true,e.rawDiagnostic);}
}
